declare interface PgClientOptions {
  host?: string;
  port?: number;
  database?: string;
  user?: string;
  password?: string;
}

declare interface PgQueryConfig {
  text: string;
  values?: string[];
}

declare interface PgQueryResult {
  text: string;
  values: string[];
}

declare interface PgClient {
  options: PgClientOptions;
  query(config: PgQueryConfig): PgQueryResult;
}

declare const pg: {
  createClient(options: PgClientOptions): PgClient;
};

export default pg;
